import axios from 'axios'
import { useSnackbar } from 'notistack'
import {
  type ChangeEvent,
  type ClipboardEvent,
  type DragEvent,
  forwardRef,
  useCallback,
  useImperativeHandle,
  useRef
} from 'react'
import { useAuthHeader } from 'react-auth-kit'
import { useParams } from 'react-router'

import { Color } from '@tiptap/extension-color'
import { Highlight } from '@tiptap/extension-highlight'
import { Link } from '@tiptap/extension-link'
import { Placeholder } from '@tiptap/extension-placeholder'
import { TaskItem } from '@tiptap/extension-task-item'
import { TaskList } from '@tiptap/extension-task-list'
import { TextAlign } from '@tiptap/extension-text-align'
import { TextStyle } from '@tiptap/extension-text-style'
import { Underline } from '@tiptap/extension-underline'
import { type Editor, EditorContent, useEditor } from '@tiptap/react'
import { StarterKit } from '@tiptap/starter-kit'

import { IMAGE_UPLOAD_MESSAGE } from 'src/data/messages'

import { ResizableImage } from './ResizableImageExtension'
import './TextEditor.css'
import EditorToolbar from './Toolbar'

/* ------------------------------------------------------------------ */
/*  Public ref handle – consumers use this instead of Editor instance */
/* ------------------------------------------------------------------ */

export interface TextEditorHandle {
  getHTML: () => string
  setHTML: (html: string) => void
  getEditor: () => Editor | null
}

/* ------------------------------------------------------------------ */
/*  Props                                                              */
/* ------------------------------------------------------------------ */

interface TextEditorProps {
  initialValue: string
  toolbarItems: string[][]
  imageUploadEndpoint?: string
}

/* ------------------------------------------------------------------ */
/*  Component                                                          */
/* ------------------------------------------------------------------ */

const TextEditor = forwardRef<TextEditorHandle, TextEditorProps>(
  ({ initialValue, toolbarItems, imageUploadEndpoint }, ref) => {
    const params = useParams()
    const { enqueueSnackbar } = useSnackbar()
    const authHeader = useAuthHeader()
    const fileInputRef = useRef<HTMLInputElement>(null)

    /* ---- image upload ---- */
    const uploadImage = useCallback(
      async (blob: Blob | File): Promise<string> => {
        try {
          const formData = new FormData()
          formData.append('img', blob)

          const endpoint = imageUploadEndpoint || `${process.env.REACT_APP_APIHOST}/club/${params.id}/recruit/img`

          const result = await axios.post(endpoint, formData, {
            headers: { Authorization: authHeader() }
          })

          return result.data.url
        } catch (error) {
          if (axios.isAxiosError(error) && error.response?.status === 413) {
            enqueueSnackbar(IMAGE_UPLOAD_MESSAGE.TOO_LARGE, { variant: 'error' })
          } else if (axios.isAxiosError(error) && error.response?.status === 400) {
            enqueueSnackbar(IMAGE_UPLOAD_MESSAGE.WRONG_FORMAT, { variant: 'error' })
          } else {
            enqueueSnackbar(IMAGE_UPLOAD_MESSAGE.UPLOAD_FAIL, { variant: 'error' })
          }
          throw error
        }
      },
      [authHeader, enqueueSnackbar, imageUploadEndpoint, params.id]
    )

    /* ---- TipTap editor instance ---- */
    const editor = useEditor({
      extensions: [
        StarterKit.configure({
          heading: { levels: [1, 2, 3] },
          codeBlock: { HTMLAttributes: { class: 'code-block' } }
        }),
        Placeholder.configure({ placeholder: '내용을 입력하세요...' }),
        TextStyle,
        Color,
        Highlight.configure({ multicolor: true }),
        Underline,
        TextAlign.configure({ types: ['heading', 'paragraph'] }),
        Link.configure({ openOnClick: false, autolink: true }),
        TaskList,
        TaskItem.configure({ nested: true }),
        ResizableImage
      ],
      content: initialValue || '',
      editorProps: {
        attributes: {
          class: 'tiptap-editor'
        }
      }
    })

    /* ---- expose handle via ref ---- */
    useImperativeHandle(
      ref,
      () => ({
        getHTML: () => editor?.getHTML() ?? '',
        setHTML: (html: string) => {
          editor?.commands.setContent(html)
        },
        getEditor: () => editor
      }),
      [editor]
    )

    /* ---- file input handler for image upload ---- */
    const handleImageUpload = useCallback(async () => {
      fileInputRef.current?.click()
    }, [])

    const handleFileChange = useCallback(
      async (e: ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0]
        if (!file || !editor) return

        try {
          const url = await uploadImage(file)
          editor
            .chain()
            .focus()
            .insertContent({
              type: 'resizableImage',
              attrs: { src: url, alt: '첨부 이미지', alignment: 'center' }
            })
            .run()
        } catch {
          // error handled in uploadImage
        }

        // reset input so the same file can be uploaded again
        if (fileInputRef.current) fileInputRef.current.value = ''
      },
      [editor, uploadImage]
    )

    /* ---- drag-and-drop / paste image handling ---- */
    const handleDrop = useCallback(
      async (e: DragEvent) => {
        const files = e.dataTransfer?.files
        if (!files?.length || !editor) return

        const file = files[0]
        if (!file.type.startsWith('image/')) return

        e.preventDefault()
        try {
          const url = await uploadImage(file)
          editor
            .chain()
            .focus()
            .insertContent({
              type: 'resizableImage',
              attrs: { src: url, alt: '첨부 이미지', alignment: 'center' }
            })
            .run()
        } catch {
          // handled
        }
      },
      [editor, uploadImage]
    )

    const handlePaste = useCallback(
      async (e: ClipboardEvent) => {
        const items = e.clipboardData?.items
        if (!items || !editor) return

        for (let i = 0; i < items.length; i++) {
          if (items[i].type.startsWith('image/')) {
            e.preventDefault()
            const file = items[i].getAsFile()
            if (!file) continue
            try {
              const url = await uploadImage(file)
              editor
                .chain()
                .focus()
                .insertContent({
                  type: 'resizableImage',
                  attrs: { src: url, alt: '첨부 이미지', alignment: 'center' }
                })
                .run()
            } catch {
              // handled
            }
            return
          }
        }
      },
      [editor, uploadImage]
    )

    if (!editor) return null

    const hasImage = toolbarItems.some(group => group.includes('image'))

    return (
      <div className="tiptap-editor-root">
        <EditorToolbar
          editor={editor}
          toolbarItems={toolbarItems}
          onImageUpload={hasImage ? handleImageUpload : undefined}
        />
        <div
          className="tiptap-editor-content"
          role="application"
          style={{ height: window.innerWidth > 1000 ? '80vh' : '60vh' }}
          onDrop={hasImage ? handleDrop : undefined}
          onPaste={hasImage ? handlePaste : undefined}
        >
          <EditorContent editor={editor} />
        </div>
        {hasImage && (
          <input
            ref={fileInputRef}
            type="file"
            accept="image/jpeg,image/jpg,image/png,image/webp"
            style={{ display: 'none' }}
            onChange={handleFileChange}
          />
        )}
      </div>
    )
  }
)

TextEditor.displayName = 'TextEditor'

export default TextEditor
