import React, { useCallback, useEffect, useRef, useState } from 'react'

import { FormatAlignCenter, FormatAlignLeft, FormatAlignRight } from '@mui/icons-material'
import { Node, mergeAttributes } from '@tiptap/react'
import { type NodeViewProps, NodeViewWrapper, ReactNodeViewRenderer } from '@tiptap/react'

/** Alignment options for images */
export type ImageAlignment = 'left' | 'center' | 'right'

/** Attributes stored on the image node */
interface ResizableImageAttributes {
  src: string
  alt: string
  title: string
  width: number | null
  alignment: ImageAlignment
}

/* ------------------------------------------------------------------ */
/*  React NodeView – renders the image with resize handles            */
/* ------------------------------------------------------------------ */

const ResizableImageComponent: React.FC<NodeViewProps> = ({ node, updateAttributes, selected }) => {
  const { src, alt, title, width, alignment } = node.attrs as ResizableImageAttributes
  const containerRef = useRef<HTMLDivElement>(null)
  const imgRef = useRef<HTMLImageElement>(null)
  const [isResizing, setIsResizing] = useState(false)
  const [showToolbar, setShowToolbar] = useState(false)

  const justifyMap: Record<ImageAlignment, string> = {
    left: 'flex-start',
    center: 'center',
    right: 'flex-end'
  }

  /* ---- resize logic ---- */
  const handleMouseDown = useCallback(
    (e: React.MouseEvent) => {
      e.preventDefault()
      e.stopPropagation()
      setIsResizing(true)

      const startX = e.clientX
      const startWidth = imgRef.current?.offsetWidth ?? width ?? 300

      const onMouseMove = (moveEvent: MouseEvent) => {
        const diff = moveEvent.clientX - startX
        const newWidth = Math.max(100, startWidth + diff)
        updateAttributes({ width: Math.round(newWidth) })
      }

      const onMouseUp = () => {
        setIsResizing(false)
        document.removeEventListener('mousemove', onMouseMove)
        document.removeEventListener('mouseup', onMouseUp)
      }

      document.addEventListener('mousemove', onMouseMove)
      document.addEventListener('mouseup', onMouseUp)
    },
    [updateAttributes, width]
  )

  /* ---- touch resize for mobile ---- */
  const handleTouchStart = useCallback(
    (e: React.TouchEvent) => {
      e.stopPropagation()
      setIsResizing(true)

      const startX = e.touches[0].clientX
      const startWidth = imgRef.current?.offsetWidth ?? width ?? 300

      const onTouchMove = (moveEvent: TouchEvent) => {
        const diff = moveEvent.touches[0].clientX - startX
        const newWidth = Math.max(100, startWidth + diff)
        updateAttributes({ width: Math.round(newWidth) })
      }

      const onTouchEnd = () => {
        setIsResizing(false)
        document.removeEventListener('touchmove', onTouchMove)
        document.removeEventListener('touchend', onTouchEnd)
      }

      document.addEventListener('touchmove', onTouchMove)
      document.addEventListener('touchend', onTouchEnd)
    },
    [updateAttributes, width]
  )

  /* close toolbar on outside click */
  useEffect(() => {
    if (!showToolbar) return
    const handleOutside = (e: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(e.target as HTMLElement)) {
        setShowToolbar(false)
      }
    }
    document.addEventListener('mousedown', handleOutside)
    return () => document.removeEventListener('mousedown', handleOutside)
  }, [showToolbar])

  return (
    <NodeViewWrapper
      as="div"
      className={`resizable-image-wrapper${selected ? ' selected' : ''}`}
      style={{ display: 'flex', justifyContent: justifyMap[alignment ?? 'center'] }}
    >
      <div
        ref={containerRef}
        className={`resizable-image-container${selected || showToolbar ? ' active' : ''}`}
        style={{ width: width ? `${width}px` : 'auto', position: 'relative', display: 'inline-block' }}
        onClick={() => setShowToolbar(true)}
      >
        <img
          ref={imgRef}
          src={src}
          alt={alt || ''}
          title={title || ''}
          style={{
            width: '100%',
            display: 'block',
            cursor: isResizing ? 'col-resize' : 'default'
          }}
          draggable={false}
        />

        {/* Resize handles – visible on select/focus */}
        {(selected || showToolbar) && (
          <>
            <div
              className="resize-handle resize-handle-right"
              onMouseDown={handleMouseDown}
              onTouchStart={handleTouchStart}
            />
            <div
              className="resize-handle resize-handle-left"
              onMouseDown={e => {
                e.preventDefault()
                e.stopPropagation()
                setIsResizing(true)

                const startX = e.clientX
                const startWidth = imgRef.current?.offsetWidth ?? width ?? 300

                const onMouseMove = (moveEvent: MouseEvent) => {
                  const diff = startX - moveEvent.clientX
                  const newWidth = Math.max(100, startWidth + diff)
                  updateAttributes({ width: Math.round(newWidth) })
                }

                const onMouseUp = () => {
                  setIsResizing(false)
                  document.removeEventListener('mousemove', onMouseMove)
                  document.removeEventListener('mouseup', onMouseUp)
                }

                document.addEventListener('mousemove', onMouseMove)
                document.addEventListener('mouseup', onMouseUp)
              }}
            />
          </>
        )}

        {/* Floating alignment toolbar */}
        {showToolbar && !isResizing && (
          <div className="image-align-toolbar">
            {(['left', 'center', 'right'] as const).map(align => (
              <button
                key={align}
                type="button"
                className={`image-align-btn${alignment === align ? ' active' : ''}`}
                onClick={e => {
                  e.stopPropagation()
                  updateAttributes({ alignment: align })
                }}
                title={`${align.charAt(0).toUpperCase() + align.slice(1)} 정렬`}
              >
                {align === 'left' && <FormatAlignLeft />}
                {align === 'center' && <FormatAlignCenter />}
                {align === 'right' && <FormatAlignRight />}
              </button>
            ))}
            {/* Percentage resize buttons */}
            <span className="image-align-separator" />
            {[25, 50, 75, 100].map(pct => (
              <button
                key={pct}
                type="button"
                className="image-align-btn image-size-btn"
                onClick={e => {
                  e.stopPropagation()
                  const editorEl = containerRef.current?.closest('.tiptap-editor')
                  const editorWidth = editorEl?.clientWidth ?? 600
                  updateAttributes({ width: Math.round(editorWidth * (pct / 100)) })
                }}
                title={`${pct}%`}
              >
                {pct}%
              </button>
            ))}
          </div>
        )}
      </div>
    </NodeViewWrapper>
  )
}

/* ------------------------------------------------------------------ */
/*  TipTap Node extension definition                                  */
/* ------------------------------------------------------------------ */

export const ResizableImage = Node.create({
  name: 'resizableImage',
  group: 'block',
  atom: true,
  draggable: true,

  addAttributes() {
    return {
      src: { default: null },
      alt: { default: '' },
      title: { default: '' },
      width: { default: null },
      alignment: { default: 'center' }
    }
  },

  parseHTML() {
    return [
      {
        tag: 'img[src]',
        getAttrs: element => {
          const el = element as HTMLElement
          const img = el.tagName === 'IMG' ? el : el.querySelector('img')
          if (!img) return false

          const imgEl = img as HTMLImageElement
          const style = imgEl.style
          const widthAttr = imgEl.getAttribute('width')
          const widthStyle = style.width

          let width: number | null = null
          if (widthAttr) width = parseInt(widthAttr, 10)
          else if (widthStyle && widthStyle.endsWith('px')) width = parseInt(widthStyle, 10)

          let alignment: ImageAlignment = 'center'
          const parentStyle = imgEl.parentElement?.style
          if (parentStyle?.textAlign === 'left' || parentStyle?.justifyContent?.includes('start')) alignment = 'left'
          else if (parentStyle?.textAlign === 'right' || parentStyle?.justifyContent?.includes('end'))
            alignment = 'right'
          // Check the image's own data attribute
          const dataAlign = imgEl.getAttribute('data-alignment') as ImageAlignment | null
          if (dataAlign) alignment = dataAlign

          return {
            src: imgEl.getAttribute('src'),
            alt: imgEl.getAttribute('alt') || '',
            title: imgEl.getAttribute('title') || '',
            width: isNaN(width as number) ? null : width,
            alignment
          }
        }
      }
    ]
  },

  renderHTML({ HTMLAttributes }) {
    const { alignment, width, ...rest } = HTMLAttributes
    const imgAttrs: Record<string, string> = {
      ...rest,
      'data-alignment': alignment ?? 'center'
    }
    if (width) {
      imgAttrs.width = String(width)
      imgAttrs.style = `width: ${width}px;`
    }

    const wrapperStyle =
      alignment === 'left' ? 'text-align: left;' : alignment === 'right' ? 'text-align: right;' : 'text-align: center;'

    return ['div', { style: wrapperStyle, class: 'image-container' }, ['img', imgAttrs]]
  },

  addNodeView() {
    return ReactNodeViewRenderer(ResizableImageComponent)
  }
})
