import React, { useCallback, useRef, useState } from 'react'

import {
  CheckBox,
  Code,
  FormatBold,
  FormatItalic,
  FormatListBulleted,
  FormatListNumbered,
  FormatQuote,
  FormatStrikethrough,
  FormatUnderlined,
  HorizontalRule,
  Image,
  Link,
  Redo,
  Undo
} from '@mui/icons-material'
import type { Editor } from '@tiptap/react'

/* ------------------------------------------------------------------ */
/*  Link insertion dialog                                              */
/* ------------------------------------------------------------------ */

const LinkButton: React.FC<{ editor: Editor }> = ({ editor }) => {
  const [showInput, setShowInput] = useState(false)
  const inputRef = useRef<HTMLInputElement>(null)

  const handleSubmit = useCallback(() => {
    const url = inputRef.current?.value?.trim()
    if (url) {
      editor.chain().focus().extendMarkRange('link').setLink({ href: url }).run()
    }
    setShowInput(false)
  }, [editor])

  const handleClick = useCallback(() => {
    if (editor.isActive('link')) {
      editor.chain().focus().unsetLink().run()
      return
    }
    setShowInput(true)
    setTimeout(() => inputRef.current?.focus(), 50)
  }, [editor])

  const handleKeyDown = useCallback(
    (e: React.KeyboardEvent) => {
      if (e.key === 'Enter') {
        e.preventDefault()
        handleSubmit()
      } else if (e.key === 'Escape') {
        setShowInput(false)
      }
    },
    [handleSubmit]
  )

  return (
    <span style={{ position: 'relative', display: 'inline-flex' }}>
      <button type="button" onClick={handleClick} className={editor.isActive('link') ? 'active' : ''} title="링크">
        <Link />
      </button>
      {showInput && (
        <span
          style={{
            position: 'absolute',
            top: '100%',
            left: 0,
            zIndex: 30,
            display: 'flex',
            gap: 4,
            padding: 6,
            background: '#fff',
            border: '1px solid #d1d5db',
            borderRadius: 6,
            boxShadow: '0 4px 12px rgba(0,0,0,0.12)',
            marginTop: 4
          }}
        >
          <input
            ref={inputRef}
            type="url"
            placeholder="https://..."
            onKeyDown={handleKeyDown}
            style={{
              width: 200,
              padding: '4px 8px',
              border: '1px solid #d1d5db',
              borderRadius: 4,
              fontSize: 13
            }}
          />
          <button type="button" onClick={handleSubmit} style={{ padding: '4px 8px', fontSize: 12 }}>
            확인
          </button>
        </span>
      )}
    </span>
  )
}

/* ------------------------------------------------------------------ */
/*  Toolbar component                                                  */
/* ------------------------------------------------------------------ */

interface EditorToolbarProps {
  editor: Editor
  toolbarItems: string[][]
  onImageUpload?: () => void
}

const EditorToolbar: React.FC<EditorToolbarProps> = ({ editor, toolbarItems, onImageUpload }) => {
  /** Maps a toolbar item key to a rendered button */
  const renderItem = (key: string) => {
    switch (key) {
      case 'heading':
        return (
          <select
            key={key}
            className="tiptap-heading-select"
            value={
              editor.isActive('heading', { level: 1 })
                ? '1'
                : editor.isActive('heading', { level: 2 })
                ? '2'
                : editor.isActive('heading', { level: 3 })
                ? '3'
                : '0'
            }
            onChange={e => {
              const level = Number(e.target.value)
              if (level === 0) {
                editor.chain().focus().setParagraph().run()
              } else {
                editor
                  .chain()
                  .focus()
                  .toggleHeading({ level: level as 1 | 2 | 3 })
                  .run()
              }
            }}
          >
            <option value="0">본문</option>
            <option value="1">제목 1</option>
            <option value="2">제목 2</option>
            <option value="3">제목 3</option>
          </select>
        )

      case 'bold':
        return (
          <button
            key={key}
            type="button"
            onClick={() => editor.chain().focus().toggleBold().run()}
            className={editor.isActive('bold') ? 'active' : ''}
            title="굵게"
          >
            <FormatBold />
          </button>
        )

      case 'italic':
        return (
          <button
            key={key}
            type="button"
            onClick={() => editor.chain().focus().toggleItalic().run()}
            className={editor.isActive('italic') ? 'active' : ''}
            title="기울임"
          >
            <FormatItalic />
          </button>
        )

      case 'strike':
        return (
          <button
            key={key}
            type="button"
            onClick={() => editor.chain().focus().toggleStrike().run()}
            className={editor.isActive('strike') ? 'active' : ''}
            title="취소선"
          >
            <FormatStrikethrough />
          </button>
        )

      case 'underline':
        return (
          <button
            key={key}
            type="button"
            onClick={() => editor.chain().focus().toggleUnderline().run()}
            className={editor.isActive('underline') ? 'active' : ''}
            title="밑줄"
          >
            <FormatUnderlined />
          </button>
        )

      case 'hr':
        return (
          <button
            key={key}
            type="button"
            onClick={() => editor.chain().focus().setHorizontalRule().run()}
            title="구분선"
          >
            <HorizontalRule />
          </button>
        )

      case 'quote':
        return (
          <button
            key={key}
            type="button"
            onClick={() => editor.chain().focus().toggleBlockquote().run()}
            className={editor.isActive('blockquote') ? 'active' : ''}
            title="인용문"
          >
            <FormatQuote />
          </button>
        )

      case 'ul':
        return (
          <button
            key={key}
            type="button"
            onClick={() => editor.chain().focus().toggleBulletList().run()}
            className={editor.isActive('bulletList') ? 'active' : ''}
            title="글머리 기호"
          >
            <FormatListBulleted />
          </button>
        )

      case 'ol':
        return (
          <button
            key={key}
            type="button"
            onClick={() => editor.chain().focus().toggleOrderedList().run()}
            className={editor.isActive('orderedList') ? 'active' : ''}
            title="번호 매기기"
          >
            <FormatListNumbered />
          </button>
        )

      case 'task':
        return (
          <button
            key={key}
            type="button"
            onClick={() => editor.chain().focus().toggleTaskList().run()}
            className={editor.isActive('taskList') ? 'active' : ''}
            title="체크리스트"
          >
            <CheckBox />
          </button>
        )

      case 'image':
        return onImageUpload ? (
          <button key={key} type="button" onClick={onImageUpload} title="이미지">
            <Image />
          </button>
        ) : null

      case 'link':
        return <LinkButton key={key} editor={editor} />

      case 'code':
        return (
          <button
            key={key}
            type="button"
            onClick={() => editor.chain().focus().toggleCode().run()}
            className={editor.isActive('code') ? 'active' : ''}
            title="인라인 코드"
          >
            <Code />
          </button>
        )

      case 'codeblock':
        return (
          <button
            key={key}
            type="button"
            onClick={() => editor.chain().focus().toggleCodeBlock().run()}
            className={editor.isActive('codeBlock') ? 'active' : ''}
            title="코드 블록"
          >
            {'</>'}
          </button>
        )

      case 'color':
        return (
          <input
            key={key}
            type="color"
            className="tiptap-color-input"
            title="글자 색상"
            onChange={e => editor.chain().focus().setColor(e.target.value).run()}
          />
        )

      default:
        return null
    }
  }

  return (
    <div className="tiptap-toolbar">
      {/* Undo / Redo – always shown */}
      <div className="tiptap-toolbar-group">
        <button
          type="button"
          onClick={() => editor.chain().focus().undo().run()}
          disabled={!editor.can().undo()}
          title="실행 취소"
        >
          <Undo />
        </button>
        <button
          type="button"
          onClick={() => editor.chain().focus().redo().run()}
          disabled={!editor.can().redo()}
          title="다시 실행"
        >
          <Redo />
        </button>
      </div>

      {/* Dynamic toolbar groups from toolbarItems prop */}
      {toolbarItems.map((group, gi) => (
        <div key={gi} className="tiptap-toolbar-group">
          {group.map(item => renderItem(item))}
        </div>
      ))}

      {/* Color picker – always available */}
      <div className="tiptap-toolbar-group">
        <input
          type="color"
          className="tiptap-color-input"
          title="글자 색상"
          onChange={e => editor.chain().focus().setColor(e.target.value).run()}
        />
      </div>
    </div>
  )
}

export default EditorToolbar
